CustomField.formula:
IF(
/*If Account is IMGA, stores D_B_Segmentation__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'IM Group (IMGA)'), TEXT(D_B_Segmentation__c),
IF(
/*If Account is Country Parent, stores D_B_Segmentation__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), TEXT(Parent.D_B_Segmentation__c),
IF(
/*If Account is Sales site, stores Country Parent Account's D_B_Segmentation__c by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'), TEXT(Parent.Parent.D_B_Segmentation__c),'')))
